create extension if not exists pgcrypto;
create type public.app_role as enum ('customer','admin');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,phone text,role public.app_role not null default 'customer',created_at timestamptz not null default now());
create table public.categories(id uuid primary key default gen_random_uuid(),name text not null unique,slug text not null unique,description text,image_url text,is_active boolean not null default true,created_at timestamptz not null default now());
create table public.products(id uuid primary key default gen_random_uuid(),sku text unique,name text not null,slug text not null unique,description text,category_id uuid references public.categories(id) on delete set null,price_kes numeric(12,2) check(price_kes is null or price_kes>=0),image_url text,gallery_urls text[] not null default '{}',specifications jsonb not null default '{}',is_featured boolean not null default false,is_active boolean not null default true,stock_quantity integer check(stock_quantity is null or stock_quantity>=0),stock_tracking boolean not null default false,created_at timestamptz not null default now());
create table public.services(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,description text,image_url text,is_active boolean not null default true,sort_order integer not null default 0,created_at timestamptz not null default now());
create table public.orders(id uuid primary key default gen_random_uuid(),order_number text unique not null default ('JX-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))),user_id uuid references auth.users(id) on delete set null,customer_name text not null,phone text not null,email text,county text not null,town text,delivery_address text not null,subtotal_kes numeric(12,2) not null default 0,total_kes numeric(12,2) not null default 0,status text not null default 'pending',payment_method text not null default 'mpesa',created_at timestamptz not null default now());
create table public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,product_id uuid references public.products(id) on delete set null,product_name_snapshot text not null,quantity integer not null check(quantity>0),unit_price_kes numeric(12,2),line_total_kes numeric(12,2));
create table public.payments(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,provider text not null default 'mpesa',provider_checkout_request_id text unique,provider_receipt_number text unique,amount_kes numeric(12,2) not null check(amount_kes>0),phone text not null,status text not null default 'pending',raw_callback jsonb,paid_at timestamptz,created_at timestamptz not null default now());
create table public.quotation_requests(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete set null,customer_name text not null,phone text not null,email text,item_requested text not null,quantity_scope text,county text not null,town text,notes text,status text not null default 'new',created_at timestamptz not null default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','')) on conflict(id) do nothing; return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin'); $$;
alter table public.profiles enable row level security;alter table public.categories enable row level security;alter table public.products enable row level security;alter table public.services enable row level security;alter table public.orders enable row level security;alter table public.order_items enable row level security;alter table public.payments enable row level security;alter table public.quotation_requests enable row level security;
create policy "Own profile or admin reads profiles" on public.profiles for select using(id=auth.uid() or public.is_admin());
create policy "Public reads active categories" on public.categories for select using(is_active or public.is_admin());
create policy "Admins manage categories" on public.categories for all using(public.is_admin()) with check(public.is_admin());
create policy "Public reads active products" on public.products for select using(is_active or public.is_admin());
create policy "Admins manage products" on public.products for all using(public.is_admin()) with check(public.is_admin());
create policy "Public reads active services" on public.services for select using(is_active or public.is_admin());
create policy "Admins manage services" on public.services for all using(public.is_admin()) with check(public.is_admin());
create policy "Customers read own orders" on public.orders for select using(user_id=auth.uid() or public.is_admin());
create policy "Admins manage orders" on public.orders for all using(public.is_admin()) with check(public.is_admin());
create policy "Customers read own order items" on public.order_items for select using(public.is_admin() or exists(select 1 from public.orders o where o.id=order_id and o.user_id=auth.uid()));
create policy "Admins manage order items" on public.order_items for all using(public.is_admin()) with check(public.is_admin());
create policy "Customers read own payments" on public.payments for select using(public.is_admin() or exists(select 1 from public.orders o where o.id=order_id and o.user_id=auth.uid()));
create policy "Admins manage payments" on public.payments for all using(public.is_admin()) with check(public.is_admin());
create policy "Visitors submit quotations" on public.quotation_requests for insert with check(user_id is null or user_id=auth.uid());
create policy "Admins read quotations" on public.quotation_requests for select using(public.is_admin());
create policy "Admins update quotations" on public.quotation_requests for update using(public.is_admin()) with check(public.is_admin());
-- Keep service-role secrets server-side only. Verify M-Pesa callbacks before updating payment/order status.
